pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner, address owner, address spender) public {
        vm.assume(newOwner != address(0));
        vm.assume(owner != address(0));
        vm.assume(spender != address(0));

        // Initial call to allowance to trigger any side effects
        c.allowance(owner, spender);

        // Attempt to transfer ownership to a non-zero address
        address oldOwner = c.owner();
        bool success = false;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {}

        // The rule: either the transfer reverted or the owner remains the same
        assertTrue(success == false || c.owner() == oldOwner);
    }
}

