// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address from, address to, uint256 amount) public {
        // Bound amount to avoid overflow and ensure realistic values
        amount = bound(amount, 0, 1e30);
        // Avoid zero addresses for transfers
        vm.assume(from != address(0) && to != address(0));
        // Avoid using the pair address directly in transfer calls that might revert
        vm.assume(from != c.pairAddress() && to != c.pairAddress());
        // Use prank to simulate from being the sender
        vm.prank(from);
        // Try to transfer tokens, which may revert for various reasons
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
        // If transfer succeeded, then totalSupply must be >= sum of balances of from and to
        // After the transfer, the sum of balances of from and to should be consistent with totalSupply
        // We check that totalSupply is not zero if there were any transfers that increased supply?
        // Actually, better: after any successful transfer, totalSupply must be at least the balance of any address whose balance was affected.
        // The simplest invariant: totalSupply >= balanceOf(from) + balanceOf(to) ? Not necessarily, because tokens could have been burned.
        // A more robust invariant: totalSupply() must be at least the maximum of the two balances.
        // But the bug is that totalSupply returns 0, so if any balance is >0, the property fails.
        // So we check: after the transfer, if either balance is >0, then totalSupply > 0.
        if (success) {
            uint256 balFrom = c.balanceOf(from);
            uint256 balTo = c.balanceOf(to);
            // If either participant has a non-zero balance, totalSupply must be non-zero
            assertTrue(!(balFrom > 0 || balTo > 0) || c.totalSupply() > 0);
        }
    }
}

