pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount, uint256 approveAmt) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        vm.assume(from != to);
        vm.assume(approveAmt > 0);
        vm.assume(amount <= approveAmt);
        vm.assume(amount > 0);
        c.setWhite(from, true);
        c.setWhite(to, true);
        // mint to from
        vm.prank(from);
        c.approve(address(0xdead), approveAmt);
        // transfer from from to to, consuming allowance
        vm.prank(from);
        c.transferFrom(from, to, amount);
        // check allowance is zero
        assertTrue(c.allowance(from, address(0xdead)) == 0);
    }
}

