pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(from != address(0) && to != address(0) && from != to);
        vm.assume(amount > 0 && amount <= 2000000 * 1e18);

        // Ensure from has enough tokens
        vm.assume(c.balanceOf(from) >= amount);

        // Record balance before transfer
        uint256 balanceBefore = c.balanceOf(to);

        // Perform transfer
        vm.prank(from);
        c.transfer(to, amount);

        // Rule: after a successful transfer, the recipient's balance should increase by at least amount (minus possible fees)
        uint256 balanceAfter = c.balanceOf(to);
        assertTrue(balanceAfter > balanceBefore);
    }
}

