pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount, uint256 initialAllowance) public {
        // Bound amount and allowance to realistic values
        amount = bound(amount, 0, 1_000_000 * 1e18);
        initialAllowance = bound(initialAllowance, 0, type(uint208).max); // avoid overflow of uint256 multiplication

        // Ensure from has sufficient balance
        vm.assume(c.balanceOf(from) >= amount);

        // Set allowance and transfer
        vm.prank(from);
        c.approve(address(this), initialAllowance);

        bool success;
        if (initialAllowance != type(uint256).max) {
            // Expected return value: true if allowance >= amount && balance >= amount, else revert or false
            if (initialAllowance >= amount) {
                vm.prank(address(this));
                success = c.transferFrom(from, to, amount);
                assertTrue(success, "transferFrom should succeed when allowance is sufficient");
                // Now check allowance decreased correctly
                uint256 expectedNewAllowance = initialAllowance - amount;
                assertEq(c.allowance(from, address(this)), expectedNewAllowance, "allowance should decrease by amount");
            } else {
                // Expect revert
                vm.prank(address(this));
                vm.expectRevert();
                c.transferFrom(from, to, amount);
            }
        } else {
            // Max allowance - should succeed and not decrease allowance
            vm.prank(address(this));
            success = c.transferFrom(from, to, amount);
            assertTrue(success, "transferFrom should succeed with max allowance");
            assertEq(c.allowance(from, address(this)), type(uint256).max, "max allowance should remain unchanged");
        }
    }
}

